template<class C>void fields(C&c,CraftOccupancyOwnerRef&v){Integer tag=static_cast<Integer>(v.index());c("tag",tag);if(tag<0||tag>1){c.reject("UnknownCraftOccupancyOwner","");return;}if(c.reading()){if(tag==0){if(!prepare_checkpoint_default_values<CraftOccupancyJobRef>(c).ok)return;v=CraftOccupancyJobRef{};}else {if(!prepare_checkpoint_default_values<CraftOccupancyRepairRef>(c).ok)return;v=CraftOccupancyRepairRef{};}}std::visit([&](auto&payload){fields(c,payload);},v);}
template<class C>void fields(C&c,CraftFacilityContentRef&v){Integer tag=static_cast<Integer>(v.index());c("tag",tag);if(tag<0||tag>1){c.reject("UnknownCraftOccupancyContent","");return;}if(c.reading()){if(tag==0){if(!prepare_checkpoint_default_values<CraftWipContent>(c).ok)return;v=CraftWipContent{};}else {if(!prepare_checkpoint_default_values<RepairItemContent>(c).ok)return;v=RepairItemContent{};}}std::visit([&](auto&payload){fields(c,payload);},v);}
