template<class C>void fields(C&c,PhysicalUnitInstallationSource&v){Integer tag=static_cast<Integer>(v.index());c("tag",tag);if(tag<0||tag>1){c.reject("UnknownCraftPhysicalInstallation","");return;}if(c.reading()){if(tag==0){if(!prepare_checkpoint_default_values<InstalledPhysicalUnitSource>(c).ok)return;v=InstalledPhysicalUnitSource{};}else {if(!prepare_checkpoint_default_values<ActivatedPhysicalUnitSource>(c).ok)return;v=ActivatedPhysicalUnitSource{};}}std::visit([&](auto&payload){facility_codec::record(c,payload);},v);}
