template<class C>void fields(C&c,CraftFacilityBoundaryDisposition&v){Integer tag=static_cast<Integer>(v.index());c("tag",tag);if(tag<0||tag>4){c.reject("UnknownCraftFacilityBoundaryDisposition","");return;}if(c.reading()){switch(tag){case 0:{if(!prepare_checkpoint_default_values<CraftFacilityUnchangedService>(c).ok)return;v=CraftFacilityUnchangedService{};}break;case 1:{if(!prepare_checkpoint_default_values<CraftFacilityReadmittedService>(c).ok)return;v=CraftFacilityReadmittedService{};}break;case 2:{if(!prepare_checkpoint_default_values<CraftFacilitySuspendedWithoutPlacement>(c).ok)return;v=CraftFacilitySuspendedWithoutPlacement{};}break;case 3:{if(!prepare_checkpoint_default_values<CraftFacilityRetainedPlacement>(c).ok)return;v=CraftFacilityRetainedPlacement{};}break;case 4:{if(!prepare_checkpoint_default_values<CraftFacilityClearedPlacement>(c).ok)return;v=CraftFacilityClearedPlacement{};}break;}}std::visit([&](auto&payload){fields(c,payload);},v);}
